syntax:
```c++
struct Foo {
  constexpr const int& f() { static int i = 42; return i; }
  int& f() { static int j = 100; return j; }
};

int main() {
  constexpr Foo foo_constexpr; 
  Foo foo_runtime; 
  constexpr int a = foo_constexpr.f(); // Compile-time evaluation
  int b = foo_runtime.f();       // Runtime evaluation
  std::cout << "a: " << a << std::endl; //Prints 42
  std::cout << "b: " << b << std::endl; // Prints 100
  return 0; 
}
```

